# Windows: getaddrinfo 可能遗漏虚拟网卡（如 VMware Host-Only），
# 通过 netsh 补全所有接口的 IP + 子网掩码
if not interfaces:
    try:
        import subprocess
        import re
        result = subprocess.run(
            ["netsh", "interface", "ip", "show", "addresses"],
            capture_output=True, text=True, timeout=5
        )
        current_ip = None
        for line in result.stdout.splitlines():
            m_ip = re.match(r'\s*IP Address:\s*(\S+)', line)
            m_mask = re.match(r'\s*Subnet Mask:\s*(\S+)', line)
            if m_ip:
                current_ip = m_ip.group(1)
                if current_ip == "127.0.0.1":
                    current_ip = None
            elif m_mask and current_ip:
                mask = m_mask.group(1)
                ip_parts = [int(p) for p in current_ip.split(".")]
                mask_parts = [int(p) for p in mask.split(".")]
                bcast = ".".join(
                    [str(ip_parts[i] | (255 ^ mask_parts[i])) for i in range(4)]
                )
                if (bcast, current_ip) not in interfaces:
                    interfaces.append((bcast, current_ip))
                current_ip = None
    except Exception:
        pass

