async function sendFile(uuid, file) {
    const CHUNK_SIZE = 64 * 1024; // 64KB
    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);

    // 通过聊天 WS 发 file_request
